def choose_move(observation):
    wx, hy = observation['grid_width'], observation['grid_height']
    px, py = observation['self_position']
    ox, oy = observation['opponent_position']
    resources = observation['resources']
    obstacles = set(observation['obstacles'])
    score_self = observation['scores'][0]
    score_opp = observation['scores'][1]

    def safe_move(dx, dy):
        nx, ny = px + dx, py + dy
        if 0 <= nx < wx and 0 <= ny < hy and (nx, ny) not in obstacles:
            return True
        return False

    # Prefer moves towards resources if available
    best_dir = [0,0]
    min_dist = float('inf')
    for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
        if safe_move(dx, dy):
            nx, ny = px + dx, py + dy
            dist_sum = 0
            for rx, ry in resources:
                dist_sum += abs(rx - nx) + abs(ry - ny)
            if resources and dist_sum < min_dist:
                min_dist = dist_sum
                best_dir = [dx, dy]
    # Otherwise, move towards opponent to block or go to corner
    if not resources or min_dist == float('inf'):
        dx = dy = 0
        if ox > px and safe_move(1, 0):
            dx = 1
        elif ox < px and safe_move(-1, 0):
            dx = -1
        elif oy > py and safe_move(0, 1):
            dy = 1
        elif oy < py and safe_move(0, -1):
            dy = -1
        best_dir = [dx, dy]
    return best_dir
